using System.Collections.Generic;
using Astrea.BattleActions;
using LittleLeo;
using UnityEngine;

namespace Astrea;

public class CorruptedAnimalEffects : UnitEffects
{
	[Header("Corrupted Animal Effects List")]
	[SerializeField]
	private CorruptedAnimalEffectsList corruptedAnimalEffectsList;

	[Header("Corrupted Animal Components")]
	[SerializeField]
	private CorruptedAnimalActivation corruptedAnimalActivation;

	[Header("Corrupted Animal Corruption Gauge")]
	[SerializeField]
	private CorruptedAnimalCorruptionGauge corruptedAnimalCorruptionGauge;

	[Header("Difficulty Levels")]
	[SerializeField]
	private DifficultyLevels difficultyLevels;

	private CorruptedAnimalData corruptedAnimalData;

	public bool WaveActivated;

	public CorruptedAnimalEffectsList CorruptedAnimalEffectsList => corruptedAnimalEffectsList;

	public void Initialize(CorruptedAnimalData corruptedAnimalData, bool startBattleInitialize)
	{
		this.corruptedAnimalData = corruptedAnimalData;
		RemoveAllEffectWithoutCallbacks();
		if (activeEffectsList.Count > 0)
		{
			activeEffectsList.Clear();
		}
		List<StartingEffect> currentDifficultyLevelStartingEffects = difficultyLevels.GetCurrentDifficultyLevelStartingEffects(corruptedAnimalData, startBattleInitialize);
		for (int i = 0; i < currentDifficultyLevelStartingEffects.Count; i++)
		{
			StartingEffect startingEffect = currentDifficultyLevelStartingEffects[i];
			unitFeedbackHandler.AddFeedbackAndEnqueueEffectFeedback(startingEffect.Effect, startingEffect.EffectAmount);
		}
		if (ReferenceSingleton<TurnManager>.Instance.AmbushBattle)
		{
			unitFeedbackHandler.AddFeedbackAndEnqueueEffectFeedback(corruptedAnimalEffectsList.Ambush, EffectsValues.NO_VALUE);
			unitFeedbackHandler.AddFeedbackAndEnqueueEffectFeedback(corruptedAnimalEffectsList.HiddenEffect, EffectsValues.INFINITY);
		}
		StartingEffect[] array = null;
		int currentDifficultyLevelModifyEnemiesHighestIndex = difficultyLevels.GetCurrentDifficultyLevelModifyEnemiesHighestIndex();
		array = ((corruptedAnimalData.StartingEffectsList.Count <= currentDifficultyLevelModifyEnemiesHighestIndex) ? corruptedAnimalData.StartingEffectsList.Last().startingEffects : corruptedAnimalData.StartingEffectsList[currentDifficultyLevelModifyEnemiesHighestIndex].startingEffects);
		foreach (StartingEffect startingEffect2 in array)
		{
			unitFeedbackHandler.AddFeedbackAndEnqueueEffectFeedback(startingEffect2.Effect, startingEffect2.EffectAmount);
		}
		if (!startBattleInitialize)
		{
			unitFeedbackHandler.EnqueueStartFeedbacksCoroutineActionsQueueState();
		}
		else if (ReferenceSingleton<InputManager>.Instance.IsJoystickBeingUsed)
		{
			unitEffectsJoystickInput.InitializeUnitDetailJoystickInput(corruptedAnimalData.unitDetailJoystickInput);
		}
		WaveActivated = false;
	}

	public override void AddEffect(Effect effect, int effectAmount, bool effectFeedback = true, bool callEffectsCallbacks = true, GameObject source = null, bool gainingEffectVFXAndSFX = true, int renderLayer = -1, bool ignoreNegatableByEffectEnum = false)
	{
		if (effect == corruptedAnimalEffectsList.WaveEffect && ReferenceSingleton<CellariusOmensHandler>.Instance.TridentOfDepthsWaveOmenAction != null)
		{
			effectAmount = ReferenceSingleton<CellariusOmensHandler>.Instance.TridentOfDepthsWaveOmenAction(effectAmount);
		}
		base.AddEffect(effect, effectAmount, effectFeedback, callEffectsCallbacks, source, gainingEffectVFXAndSFX, renderLayer, ignoreNegatableByEffectEnum);
		if (IsEffectActive(corruptedAnimalEffectsList.OmniSoulEffect, activateFeedback: false))
		{
			corruptedAnimalEffectsList.OmniSoulEffect.ShareEffectWithOtherAstreas(source, effect, effectAmount, base.gameObject);
		}
	}

	public void OnEndPlayerTurn()
	{
		if (IsEffectActive(effectsList.ReliefEffect, activateFeedback: false) && ReferenceSingleton<SothisOmensHandler>.Instance.ActivateTaintedKhepreshOmen(activateFeedback: true))
		{
			IsEffectActiveWithActivation(effectsList.ReliefEffect, activateFeedback: false);
		}
	}

	public override void OnStartCorruptPlayerState()
	{
		IsEffectActiveWithActivation(corruptedAnimalEffectsList.RealityDisruptionEffect);
		IsEffectActiveWithActivation(corruptedAnimalEffectsList.CorruptedRepairEffect, activateFeedback: false, updateAmount: false);
		base.OnStartCorruptPlayerState();
	}

	public override void OnEndCorruptPlayerState()
	{
	}

	public override void OnEndOfAllTurns()
	{
		base.OnEndOfAllTurns();
		if (corruptedAnimalData.EnableUnitsMiscData && corruptedAnimalData.UnitsMiscData.EnableCustomOnBeforeDrawDicePhaseEffects)
		{
			corruptedAnimalData.UnitsMiscData.OnEndOfAllTurns();
		}
		IsEffectActiveWithActivation(corruptedAnimalEffectsList.FabricateSentinelsEffect, activateFeedback: false);
		IsEffectActiveWithActivation(corruptedAnimalEffectsList.DeclineEffect, activateFeedback: false, updateAmount: false);
		IsEffectActiveWithActivation(corruptedAnimalEffectsList.HatchingChrysalisEffect, activateFeedback: false, updateAmount: false);
		IsEffectActiveWithActivation(corruptedAnimalEffectsList.GrimAwakeningEffect, activateFeedback: false, updateAmount: false);
		IsEffectActiveWithActivation(corruptedAnimalEffectsList.CorruptedDodgeEffect, activateFeedback: true, updateAmount: false);
		IsEffectActiveWithOptionalActivation(corruptedAnimalEffectsList.DiceGorgerEffect, activateFeedback: false, updateAmount: false);
		IsEffectActiveAndDecreaseEffect(effectsList.DisorientedEffect, 1);
	}

	public void OnEndInitializeBattleState()
	{
		unitFeedbackHandler.StartFeedbacksCoroutineIfAnyFeedbackOnQueue();
	}

	public override bool OnBeforeDrawDicePhaseEffects()
	{
		List<bool> list = new List<bool>();
		list.Add(base.OnBeforeDrawDicePhaseEffects());
		if (corruptedAnimalData.EnableUnitsMiscData && corruptedAnimalData.UnitsMiscData.EnableCustomOnBeforeDrawDicePhaseEffects)
		{
			corruptedAnimalData.UnitsMiscData.OnBeforeDrawDicePhaseEffects();
		}
		list.Add(IsEffectActiveWithActivation(corruptedAnimalEffectsList.HiddenEffect));
		list.Add(IsEffectActiveWithActivation(corruptedAnimalEffectsList.HiddenCorruptionSourceLinkEffect));
		if (!IsEffectActiveWithActivation(corruptedAnimalEffectsList.BoostEffect) && !IsEffectActiveWithActivation(corruptedAnimalEffectsList.BoostCorruptionSourceLinkEffect))
		{
			UnitsDiceActivation component = GetComponent<UnitsDiceActivation>();
			if (component.IsBoosted)
			{
				list.Add(item: true);
			}
			component.Boosted(boost: false);
		}
		if (ReferenceSingleton<AssetsReference>.Instance.PlayerRunStats.CurrentBattle.BattleTurnCounter == 2)
		{
			if (IsEffectActiveWithOptionalActivation(corruptedAnimalEffectsList.BlightedSoulEffect, activateFeedback: true, updateAmount: false))
			{
				ToggleHideCorruption(value: true);
				list.Add(item: true);
			}
			if (IsEffectActiveWithActivation(corruptedAnimalEffectsList.ObscureEffect, activateFeedback: true, updateAmount: false))
			{
				ToggleHideOverCorruption(value: true);
				list.Add(item: true);
			}
		}
		list.Add(IsEffectActiveWithActivation(corruptedAnimalEffectsList.SingularityGoddessEffect, activateFeedback: false));
		return list.Contains(item: true);
	}

	public void ToggleHideCorruption(bool value)
	{
		corruptedAnimalCorruptionGauge.ToggleHideCorruption(value);
	}

	public void ToggleHideOverCorruption(bool value)
	{
		corruptedAnimalCorruptionGauge.ToggleHideOverCorruption(value);
	}

	public bool EndPlayerTurnEffects()
	{
		return new List<bool> { IsEffectActiveRemoveEffect(effectsList.ShadowMantleEffect) }.Contains(item: true);
	}

	public override bool OnStartTurnEffects()
	{
		return new List<bool>
		{
			base.OnStartTurnEffects(),
			IsEffectActiveWithActivation(effectsList.RuinEffect, activateFeedback: false),
			IsEffectActiveWithActivation(effectsList.NefariousPulseEffect, activateFeedback: false),
			IsEffectActiveWithActivation(corruptedAnimalEffectsList.DecayEffect, activateFeedback: false),
			IsEffectActiveWithOptionalActivation(corruptedAnimalEffectsList.DismalCycleEffect, activateFeedback: false)
		}.Contains(item: true);
	}

	public override bool OnEndTurnEffects()
	{
		List<bool> list = new List<bool>();
		if (IsEffectActiveGetAmount(corruptedAnimalEffectsList.DeclineEffect, activateFeedback: false) > 1)
		{
			IsEffectActiveWithActivation(corruptedAnimalEffectsList.AphoticInstinctEffect);
		}
		if (!ReferenceSingleton<SothisOmensHandler>.Instance.ActivateTaintedKhepreshOmen(activateFeedback: false))
		{
			list.Add(IsEffectActiveWithActivation(effectsList.ReliefEffect, activateFeedback: false));
		}
		list.Add(base.OnEndTurnEffects());
		list.Add(IsEffectActiveWithActivation(effectsList.UnholyMistEffect));
		return list.Contains(item: true);
	}

	public void OnPurifyEffectsBeforeCurrentCorruptionUpdate(float currentCorruption, GameObject source)
	{
		if (currentCorruption > 0f && source != null)
		{
			IsEffectActiveWithActivationWithSource(effectsList.ThornEffect, source, activateFeedback: false);
			IsEffectActiveWithActivationWithSource(corruptedAnimalEffectsList.ThornCorruptionSourceLinkEffect, source, activateFeedback: false);
		}
	}

	public override void OnPurifyEffects(float currentCorruption, GameObject source, int purifyAmount)
	{
		base.OnPurifyEffects(currentCorruption, source, purifyAmount);
		if (IsEffectActive(corruptedAnimalEffectsList.EldritchConnectionEffect))
		{
			corruptedAnimalEffectsList.EldritchConnectionEffect.DealPurificationToBoss(purifyAmount);
		}
		if (corruptedAnimalData.EnableUnitsMiscData && corruptedAnimalData.UnitsMiscData.EnableCustomOnPurifyEffects)
		{
			corruptedAnimalData.UnitsMiscData.CustomOnPurifyEffects();
		}
		IsEffectActiveWithActivation(corruptedAnimalEffectsList.OutbreakEffect, activateFeedback: false, updateAmount: false);
		InvokeAlternatives.InvokeAfterMultipleFrames(ReferenceSingleton<CoroutineHandler>.Instance, ReferenceSingleton<BattleHandler>.Instance.FramesToWaitToUpdateCorruption + 1, delegate
		{
			if (currentCorruption > 0f)
			{
				IsEffectActiveWithActivationWithPurifyAmountAndSource(corruptedAnimalEffectsList.CrimsonEquinoxEffect, purifyAmount, source, activateFeedback: false, updateAmount: false);
				IsEffectActiveWithActivationWithSource(corruptedAnimalEffectsList.VengefulStabEffect, source, activateFeedback: false, updateAmount: false);
				IsEffectActiveWithActivationWithSource(corruptedAnimalEffectsList.UncontrollableMeissaEffect, source, activateFeedback: false, updateAmount: false);
				IsEffectActiveWithActivation(corruptedAnimalEffectsList.UnpredictableEffect, activateFeedback: false, updateAmount: false);
			}
		});
	}

	public bool OnPurgedEffects()
	{
		return new List<bool>
		{
			IsEffectActiveWithActivation(corruptedAnimalEffectsList.CursedSpiritEffect, activateFeedback: false),
			IsEffectActiveWithActivation(corruptedAnimalEffectsList.BlightedSoulEffect, activateFeedback: false),
			IsEffectActiveWithActivation(corruptedAnimalEffectsList.CursedBubbleEffect),
			IsEffectActiveWithOptionalActivation(corruptedAnimalEffectsList.DeepnessPresenceEffect),
			IsEffectActiveWithActivation(corruptedAnimalEffectsList.DeathBombEffect, activateFeedback: false),
			IsEffectActiveWithActivation(corruptedAnimalEffectsList.WaveEffect, activateFeedback: false)
		}.Contains(item: true);
	}

	public void OnRerollEffects(int diceRerolledAmount)
	{
		int num = IsEffectActiveGetAmount(corruptedAnimalEffectsList.BladesOfPainEffect, activateFeedback: false);
		if (num > 0)
		{
			corruptedAnimalEffectsList.BladesOfPainEffect.ActivateAction(base.gameObject, diceRerolledAmount, num);
		}
	}

	public override void OnSpecificDiceCasted(Dice dice)
	{
		for (int i = 0; i < corruptedAnimalEffectsList.OnDicePlayedEffects.Length; i++)
		{
			ActivateDiceSpecificEffects(corruptedAnimalEffectsList.OnDicePlayedEffects[i], dice, updateAmount: false);
		}
		ActivateDiceSpecificEffects(corruptedAnimalEffectsList.CorruptedMoonlightEffect, dice);
		IsEffectActiveWithActivation(corruptedAnimalEffectsList.CrimsonSolsticeEffect, activateFeedback: false, updateAmount: false);
		base.OnSpecificDiceCasted(dice);
	}

	public override void OnRuneCasted(RuneInstance runeInstance)
	{
		IsEffectActiveWithActivationWithSource(corruptedAnimalEffectsList.SingularityGoddessEffect, null, activateFeedback: false, updateAmount: false);
		IsEffectActiveWithActivation(corruptedAnimalEffectsList.CrimsonSolsticeEffect, activateFeedback: false, updateAmount: false);
		IsEffectActiveWithActivation(corruptedAnimalEffectsList.DismalCycleEffect);
		IsEffectActiveWithActivationWithSource(corruptedAnimalEffectsList.SaiphsHelp, null, activateFeedback: false, updateAmount: false);
		IsEffectActiveWithActivationWithSource(corruptedAnimalEffectsList.VirtueEaterEffect, null, activateFeedback: false, updateAmount: false);
		if (!runeInstance.Rune.BattleAction.BaseBattleActionData.HasMandatoryBattleActionInteractionEnum())
		{
			IsEffectActiveWithActivation(corruptedAnimalEffectsList.EldritchInfluenceEffect);
		}
	}

	public override void ToggleActionValueModifier(ActionValueModifier actionValueModifier)
	{
		corruptedAnimalActivation.ToggleActionValueModifier(actionValueModifier);
	}

	public override void UpdateActionValueModifier()
	{
		corruptedAnimalActivation.UpdateActionValueModifier();
	}

	public int IsEnemyCriticalCorruptionCheckCritical(int corruptionAmount)
	{
		int num = IsEffectActiveGetAmount(corruptedAnimalEffectsList.CorruptedCriticalEffect, activateFeedback: false);
		if (num > 0)
		{
			return corruptedAnimalEffectsList.CorruptedCriticalEffect.GetCorruptionAmount(num, corruptionAmount, this);
		}
		return corruptionAmount;
	}

	public float IsHiddenActiveDecreaseAndLeaveHiddenAnimation()
	{
		if (IsEffectActiveAndDecreaseEffect(corruptedAnimalEffectsList.HiddenEffect, 1))
		{
			return corruptedAnimalEffectsList.HiddenEffect.LeaveHiddenAnimationGetHiddenAnimationTime(base.gameObject);
		}
		return 0f;
	}

	public bool IsStunningAuraActive()
	{
		return IsEffectActive(corruptedAnimalEffectsList.StunningAuraEffect, activateFeedback: true, enqueueFeedback: false);
	}

	public bool IsSilencingAuraActive(bool feedback)
	{
		return IsEffectActive(corruptedAnimalEffectsList.SilencingAuraEffect, feedback);
	}

	public bool IsSilencingAuraActiveWithActivation()
	{
		return IsEffectActiveWithActivation(corruptedAnimalEffectsList.SilencingAuraEffect, activateFeedback: false);
	}

	public bool IsParalyzingAuraActive()
	{
		return IsEffectActive(corruptedAnimalEffectsList.ParalyzingAuraEffect, activateFeedback: false);
	}

	public bool IsAphoticInstinctActiveAndWithNoDoom()
	{
		if (IsEffectActive(corruptedAnimalEffectsList.AphoticInstinctEffect, activateFeedback: false) && !IsEffectActive(effectsList.DoomEffect, activateFeedback: false))
		{
			IsEffectActive(corruptedAnimalEffectsList.AphoticInstinctEffect);
			return true;
		}
		return false;
	}

	public int IsDuskyConversionActive()
	{
		return IsEffectActiveGetAmount(corruptedAnimalEffectsList.DuskyConversion, activateFeedback: false);
	}

	public void IsDeepnessPresenceActiveWithActivation()
	{
		IsEffectActiveWithActivation(corruptedAnimalEffectsList.DeepnessPresenceEffect, activateFeedback: false);
	}

	public bool IsEnemyCursedSandsCheckCursedSands(DiceInstance diceInstance)
	{
		int num = IsEffectActiveGetAmount(corruptedAnimalEffectsList.CursedSandsEffect, activateFeedback: false);
		if (num > 0 && corruptedAnimalEffectsList.CursedSandsEffect.CheckCursedSands(diceInstance, num, this))
		{
			return true;
		}
		return false;
	}

	public bool IsDiceGorgerActiveWithAtLeastOneAmount()
	{
		int num = IsEffectActiveGetAmount(corruptedAnimalEffectsList.DiceGorgerEffect, activateFeedback: false);
		IsEffectActiveWithActivation(corruptedAnimalEffectsList.DiceGorgerEffect, activateFeedback: false, updateAmount: false);
		return num > 0;
	}

	public int IsDeclineActiveGetAmount()
	{
		return IsEffectActiveGetAmount(corruptedAnimalEffectsList.DeclineEffect, activateFeedback: false);
	}

	public void ClearFeedbacksActionList()
	{
		unitFeedbackHandler.ClearFeedbacksActionList();
	}
}
